<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder\UserProfilePreferredUsernameAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfilePreferredUsernameAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserProfilePreferredUsernameAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getPreferredUsername returns null on a freshly created holder.
     */
    public function testPreferredUsernameNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePreferredUsernameAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isPreferredUsernameAssigned());
        $this->assertNull($holder->getPreferredUsername());
    }
}
class ImplWithUserProfilePreferredUsernameAttributeHolderUnitTest
{
    use UserProfilePreferredUsernameAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedPreferredUsernameRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultPreferredUsername();
    }
}
